"""Render a static executive summary from explicitly classified evidence."""
import hashlib
import html
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
def build():
    records = json.loads((ROOT/'knowledge/focus-sites.json').read_text())
    rows = []
    for r in records:
        e = html.escape
        rows.append(f"<tr><td><a href='{e(r['source'])}'>GEMSDOE{r['site']}</a></td><td><code>{e(r['file'])}</code></td><td>{r['reported']}<br><small>USER-REPORTED historical result; not ORGANIZER-CONFIRMED</small></td><td>Unavailable — no comparable compliant HOLDOUT-DTI</td><td>{e(r['uniqueness'])}</td><td><strong>DO NOT SUBMIT</strong></td></tr>")
    body = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GEMS • Executive submission review</title><style>
:root{font-family:system-ui,sans-serif;color:#182b36;background:#f3f6f7}body{max-width:1250px;margin:auto;padding:32px}a{color:#005f77}h1{font-size:2.4rem}h2{margin-top:2.5rem}.alert{border-left:6px solid #a32b22;background:#fff0ed;padding:22px;border-radius:8px}.card{background:white;border:1px solid #d5dfe2;padding:22px;border-radius:10px;margin:20px 0}.scroll{overflow:auto}table{border-collapse:collapse;min-width:1000px;width:100%;background:white}td,th{padding:14px;text-align:left;border-bottom:1px solid #d5dfe2;vertical-align:top}th{background:#183e4b;color:white}code{overflow-wrap:anywhere}small{color:#56636c}nav{display:flex;gap:20px;flex-wrap:wrap}li{margin:10px 0}</style><nav><b>GEMS / Research control</b><a href="#portfolio">Nine-site review</a><a href="submission.html">Submission instructions</a><a href="research.html">Hypotheses &amp; limits</a><a href="audit.json">Machine-readable audit</a></nav><h1>Executive submission review</h1><p>Review date: 26 October 2026 · autonomous audit, not organizer certification</p><section class="alert"><h2 style="margin-top:0">NO TIFF CLEARED FOR DOWNLOAD AND SUBMISSION</h2><p>No competition TIFF was generated. There is no assigned method lane, no cached feature stack, no validated fold design and no complete raster registry in this checkout. Producing an arbitrary or copied TIFF would violate the requested protocol.</p><p><strong>Download:</strong> unavailable. <strong>Estimated leaderboard score:</strong> unavailable. <strong>Weekly slots used by this session:</strong> none.</p></section><section class="card"><h2 style="margin-top:0">Decision in brief</h2><p>The supplied results rank GEMSDOE32 first among the nine sites at 0.2778, followed by GEMSDOE36 at 0.2750. These are historical user reports, not organizer-confirmed receipts or estimates for a new file. The prompt gives conflicting overall leaderboard highs (0.3195 and 0.4413); neither is verified here.</p><p>The upstream GEMSDOE32 review attributes the winning family to sparse emission and pruning near catalogued faults. It reports duplicates across sites and withdraws a later candidate over leakage and uniqueness concerns. Those byte-level claims are <strong>upstream reports, not independently recomputed here</strong>.</p><p>Different filenames, compression or a handful of moved dots do not prove scientific novelty. The literal all-registry overlap threshold remains binding even if a dense calibration lattice makes it difficult to pass.</p></section><h2 id="portfolio">Per-site executive summary</h2><p>Historical identifiers below identify references for learning, not recommended downloads. The .tif suffix is inferred from the user-supplied identifier; exact upstream paths are not verified. No file has full submission clearance. Each source opens the pinned repository snapshot inspected in this review.</p><div class="scroll"><table><thead><tr><th>Site / evidence</th><th>Historical leading filename</th><th>Historical result</th><th>New-file estimate</th><th>Unique?</th><th>Download &amp; submit?</th></tr></thead><tbody>''' + ''.join(rows) + '''</tbody></table></div><section class="card"><h2 style="margin-top:0">Why pruning can help — and what it does not prove</h2><p>The shared instrument uses a 300 m triangular kernel and Tversky weights α=0.2, β=0.8. Additional predictions can add false-positive mass without improving the maximum coverage of a withheld fault pixel. Sparse dots can therefore outperform a dense ridge. Removing low-value dots is a plausible explanation for the supplied score ladder, not a causal experiment on hidden organizer labels.</p><p>The precise marginal condition is ΔTP &gt; DTI × (ΔTP + αΔFP + βΔFN). A fixed “credit per dot” threshold is not universally valid because coverage saturates and one dot may affect multiple truth cells. Hidden faults are unavailable; no legitimate calculation here establishes a new score above 0.2778 or either claimed leaderboard high.</p><p>This is a fault-mapping target relevant to geothermal exploration, not a validated geothermal-vent detector. Geological confounders and external geothermal validation must be tracked separately.</p></section><h2>Evidence and official sources</h2><ul><li><a href="https://github.com/drivendataorg/gems-prize-reference-solution">Organizer-maintained reference solution</a> — README retrieved through GitHub API; CPU training supported, GPU not mandatory.</li><li><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/">Competition problem and metric</a> · <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Leaderboard</a> · <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/data/">Data</a> — links supplied for review; not fetched in this restricted environment.</li><li><a href="https://docs.nlr.gov/docs/fy26osti/96647.pdf">Rules PDF supplied in request</a> — not fetched or treated as verified.</li><li><a href="audit.json">Snapshot and provenance index</a> — owner repositories are not official scientific authorities.</li></ul><p><small>No organizer submission was made. Research budget: zero geological experiments; stopped at prerequisites, not a negative test of a geological hypothesis.</small></p></html>'''
    (ROOT/'docs/index.html').write_text(body)
    (ROOT/'docs/executive-summary.html').write_text(body)
    snapshots=[]
    for p in sorted((ROOT/'evidence/upstream').rglob('*')):
        if p.is_file(): snapshots.append(dict(path=str(p.relative_to(ROOT)),sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
    (ROOT/'docs/audit.json').write_text(json.dumps(dict(review_date='2026-10-26',approved_for_submission=False,sites=records,snapshots=snapshots),indent=2)+'\n')
if __name__=='__main__':build()
